"use client";
/* Frog, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Frog(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("frog"); }, []);
  return React.createElement("piix-pal", { "pal": "frog", ...piixAttrs(props) });
}

export default Frog;
